{
  "ideas": [
    {
      "rank": 1,
      "area": "SHOOT",
      "title": "Three-Tier Shot Hierarchy: Crisp Taps, Scaled Writs, Subdued Stream",
      "what": "Separate the three fire expressions so discrete taps and charged Writs feel authoritative and distinct, while continuous stream fire stays functional but intentionally understated.",
      "specifics": "Visuals: Give a tap shot a 40ms cyan-white muzzle diamond (1.5x ship width) and a taut projectile with a 120ms tapered ribbon trail. Scale Writ 1/2/3 projectile length (1.5x/2.2x/3.0x), core brightness, and concentric wake rings (1, 2, or 3 rings expanding over 180ms), plus a diegetic charge pip ring around the ship that locks in at each tier during rest. Keep stream bullets short, thin, 65% opacity cyan dashes with no muzzle flash. Audio: Tap = 8ms snappy 2.5kHz transient click + 70ms resonant 350Hz body + 90ms airy tail, with +/-30 cents random pitch and a subtle harmonic rise when rhythms are spaced >180ms. Writ charge during rest = quiet rising sine/chime lock at L1/L2/L3 (500Hz, 750Hz, 1125Hz, 120ms each, -12dB). Writ release = 15ms punchy sub-drop (110Hz->55Hz) + 180ms chordal brassy synth body + 350ms shimmer tail at L3. Stream = soft filtered pulse (600-1.2kHz band-passed, -8dB below taps, capped at 2 overlapping voices).",
      "evidence": "In Clip G (00:00-00:11) vs Clip E (00:00-00:11) and Clip C (00:00-00:08), continuous stream needles, single taps, and diamond Writ shots share too much of the same high-brightness white/cyan glow around the ship and similar thin laser/pew timbres, making rest-and-tap precision feel less rewarding than holding the button.",
      "risk": "Overly loud or bright Writ Level 3 blasts could mask incoming pink enemy bullets near the player ship.",
      "accessibility": "Keep muzzle flashes localized to the ship nose (<1.5x ship radius) and cap luminance transitions below 3Hz to avoid photosensitive triggers; diegetic charge rings + audio chimes let players track Writ tiers without looking at the top-left HUD."
    },
    {
      "rank": 2,
      "area": "DAMAGE",
      "title": "Physics-Driven Part Severing & Desaturated Tumbling Debris",
      "what": "Make disarming a tangible physical event where the severed weapon part detaches at the exact hit point and tumbles away with impulse and torque derived from the shot vector and hit offset.",
      "specifics": "Visuals: On part break, freeze the severed piece for 25ms with a bright cyan-white seam slash aligned normal to the shot vector. Apply linear velocity along the shot direction (e.g., 80% shot vector + 20% outward normal, 12-18 world units/sec) and angular velocity proportional to `cross(hitOffsetFromPartCenter, shotDirection)` (360-900 deg/s tumble). Immediately drop the detached mesh to 35% saturation, 45% value, and 70% opacity, sinking it -1.5 units toward the lane floor over 650ms so it passes cleanly beneath active pink bullets. Emit 6-10 directional sparks (220ms lifetime) in a 35-degree cone. On the surviving disarmed hull, show a tiny cool-blue electrical fizzle (4 particles/sec) as it banks off-screen. Audio: 12ms metallic shear transient (3.2kHz) + 110ms hollow mechanical clank (450Hz) + a 250ms pitch-dropping servo power-down wheeze (900Hz->220Hz) panned to the enemy's horizontal lane position (max 3 voices).",
      "evidence": "In Clip B (00:05-00:10), Clip C (00:01-00:06), Clip E (00:01-00:10), and Clip F (00:02-00:06), breaking parts triggers a generic expanding ring and floating text ('DISARMED' / 'PARTIAL'), while the enemy state change looks flat and lacks directional physical follow-through.",
      "risk": "Flying debris could be mistaken for active enemy projectiles or enemies if it retains high contrast or stays on the combat plane.",
      "accessibility": "Desaturating, darkening, and dropping debris below the combat plane ensures low-vision and colorblind players never confuse harmless tumbling parts with bright pink/magenta hazards."
    },
    {
      "rank": 3,
      "area": "DAMAGE",
      "title": "Density-Scaled Impact Readability, Part-Crack States & Deflection Feedback",
      "what": "Keep multi-hit salvos, progressive part damage, and invulnerable boss deflections distinct and readable without whiteout or audio mud.",
      "specifics": "Visuals: Replace large additive hit spheres with a tight 30ms emissive rim-flash on the struck part mesh only, plus a 40ms directional hit-spark V-chevron (4 particles, 90ms lifetime). As a breakable part takes damage, overlay progressive glowing amber fracture lines on that sub-mesh at 50% and 25% HP. For deflections (boss descending/talking), spawn a flat tangential hexagonal ripple on the shield/hull and ricochet the spent shot off at a 45-70 degree angle (fading over 140ms in muted slate-blue). Audio: Cap standard hit voices at 4 within any 50ms window; when hit density exceeds 3 hits/100ms, duck individual transients by -4dB and step pitch up +40 cents per consecutive hit on a target so damage reads as a clean rising contour. Deflections use a dull 15ms ceramic 'tink' (1.8kHz bandpass) + 80ms downward pitch ricochet (1.4kHz->600Hz) so players immediately stop wasting shots.",
      "evidence": "In Clip A (00:06-00:11) and Clip F (00:01-00:07), dense hits and overlapping white rings obscure enemy silhouettes and nearby pink bullets; in Clip D (00:00-00:02, 00:06-00:11) and Clip H (00:00-00:03, 00:09-00:11), boss hits and invulnerable phases trigger blinding white blooms and harsh, clipping noise bursts.",
      "risk": "Pitch-stepping on rapid stream fire can sound cartoonish if not clamped to a narrow musical interval (e.g., max +300 cents).",
      "accessibility": "Eliminating large additive white hit flashes directly protects photosensitive players and preserves bullet-to-background contrast during dense patterns."
    },
    {
      "rank": 4,
      "area": "MOVE",
      "title": "Directional RCS Thruster Puffs, Chassis Bank & Focus-Mode Tightening",
      "what": "Give ship movement and focus-slowdown immediate physical weight through opposite-vector thruster puffs, banking, and responsive propulsion audio.",
      "specifics": "Visuals: On lateral/vertical acceleration or direction reversal, fire a crisp opposite-vector RCS puff from the corresponding side/front nozzle: 5-8 stretched triangle particles, pale cyan (#90E0EF at 60% opacity), 110ms lifetime, decelerating rapidly over 0.8x ship width. Add a 12-18 degree chassis roll/pitch into the movement vector with a 90ms spring-back settle when stopping. When holding Focus (black-core ship state), pull the two aiming guide lines inward by 25%, tighten the ship's outer glow into a sharp 2px perimeter ring, and emit 4 tiny stabilizing micro-vent puffs at the corners. Audio: Direction change = 35ms pneumatic air-burst transient (1.5-4kHz bandpass, -14dB) stereo-panned to ship X. Continuous movement = subtle 160Hz-320Hz thruster hum whose cutoff frequency scales with ship speed. Focus engage/disengage = 60ms bi-directional filter sweep (down to 400Hz on engage, up on release) with a soft mechanical precision click (1 voice max).",
      "evidence": "In Clip B (00:06-00:10), Clip D (00:02-00:07), and Clip G (00:00-00:11), the ship translates across the lane as an unbanked glowing orb; switching between normal (white core) and focus (black core with reticle brackets) happens silently and without thruster reaction.",
      "risk": "Thruster particles could mimic bullets if they are round or bright pink/white.",
      "accessibility": "Using cool cyan triangular/linear puffs that die within 110ms and stay attached to the ship perimeter prevents any confusion with circular pink enemy bullets."
    },
    {
      "rank": 5,
      "area": "LANE",
      "title": "Sub-Surface Lane Conduit Traffic, Combat Reflections & Signal Pulses",
      "what": "Turn the flat lane floor into a living, deep-layered data/transport highway that reacts to ship and combat events while staying strictly in the background value/saturation range.",
      "specifics": "Visuals: Restrict all lane floor elements to Value <= 32% and Saturation <= 40% (deep navy #0A1833 to muted teal #163859 in normal sectors; deep maroon #2A0E0C to burnt umber #471A14 in boss sectors). Add 3 parallax sub-surface layers via a single multi-UV shader: (1) etched circuit/conduit grid lines scrolling at 1.0x speed, (2) 4-6 longitudinal 'traffic lanes' carrying instanced rectangular data packets (6-12 quads on screen, 15% opacity) scrolling at 1.6x speed in both directions, and (3) a soft ground-plane reflection pass (or cheap projected radial decals, 20% opacity, blurred) under the player ship, Writ shots, and boss core. When a Writ is fired or an enemy is disarmed, send a dim sub-surface shockwave pulse down the nearest floor conduit line at 15% additive brightness over 300ms. Audio: Tie sector transitions (like Clip A 00:04) or boss descents (Clip D 00:00) to a low sub-bass lane-conduit surge (65Hz-120Hz, 400ms swell, -16dB).",
      "evidence": "Across Clips A-H (e.g., Clip B 00:00-00:11 for blue, Clip D 00:00-00:11 for red-orange), the lane floor is an almost uniform, untextured gradient slab, leaving all environmental storytelling to the side space structures.",
      "risk": "High-contrast grid lines or fast-scrolling bright packets on the floor can cause visual fatigue, motion sickness, or obscure small pink bullets.",
      "accessibility": "Enforcing a strict shader clamp (max 32% brightness, zero hard white edges, soft low-contrast gradients) and offering a 'Static/Reduced Background Motion' toggle protects motion-sensitive players and keeps foreground bullets at a >4.5:1 contrast ratio."
    }
  ],
  "do_not": [
    {
      "dont": "Do not use full-screen red damage vignettes or un-clamped white screen/boss blooms (as seen in Clip B 00:09, Clip E 00:02/00:08, and Clip H 00:00-00:02/00:09).",
      "why": "Sudden high-luminance full-screen flashes risk triggering photosensitive epilepsy, blind the player to nearby pink bullets during critical dodges, and cause severe fill-rate drops on low-end Chromebook integrated GPUs."
    },
    {
      "dont": "Do not give continuous stream fire rich bass transients, screen shake, or bright muzzle flashes.",
      "why": "If holding the fire button feels and sounds visceral, players will default to arcade stream-spamming instead of engaging with the rest-charge Writ and discrete tap-shot loop."
    },
    {
      "dont": "Do not render severed enemy parts at full brightness/saturation or keep them on the same Z-plane as active bullets.",
      "why": "Tumbling debris that shares the brightness or pink/white palette of hazards will be misread as lethal projectiles, punishing players for successfully disarming enemies."
    },
    {
      "dont": "Do not use small circular or pink/magenta/orange particles for lane floor traffic, thruster puffs, or hit sparks.",
      "why": "Enemy bullets are small glowing pink/orange circles; any background or VFX element sharing that shape and hue destroys instant threat recognition at high bullet density."
    },
    {
      "dont": "Do not spawn physics-simulated 3D debris with real-time collisions, dynamic point lights, or >50 alpha-blended particles per hit.",
      "why": "Browser WebGL on school Chromebooks is heavily fill-rate and CPU bound; use simple kinematic math (`pos += vel * dt`, `rot += angVel * dt`) and vertex-colored instanced meshes instead."
    },
    {
      "dont": "Do not allow unlimited overlapping audio voices or un-attenuated high-frequency noise bursts on rapid hits (like the harsh burst in Clip D 00:06/00:11 and Clip H 00:08).",
      "why": "Unchecked WebAudio node spawning causes main-thread audio crackling on low-end laptops and ear fatigue; enforce strict polyphony caps (3-4 voices per category) and soft-clipping."
    }
  ]
}
